import {expect,it} from 'bun:test';
import {join} from 'node:path';
import {OwnedDatabase} from '../src/infrastructure/database/owned-database';
import {createSchema} from '../src/infrastructure/database/schema';
import {appendMemoryEvent,rebuildProjectionsWithReport} from '../src/infrastructure/database/event-log';
import {MemoryEventEnvelope} from '../src/domain/entities/memory-event';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
it('must reject a malformed explicit fact project instead of falling back to envelope scope',async()=>{
 const store=createOwnedTestDirectory('memory-coercion-probe-'),db=new OwnedDatabase(':memory:');
 try{
  createSchema(db);const path=join(store.dir,'events.jsonl'),time=new Date('2026-01-01T00:00:00Z');
  await appendMemoryEvent(MemoryEventEnvelope.create({eventId:'synthetic',machineId:'synthetic',sequence:1,kind:'learning',operation:'add',occurredAt:time,observedAt:time,
   scope:{project:'synthetic',visibility:'project'},provenance:{source:'test',actor:'test',method:'fixture'},privacy:{redactionState:'none',containsSensitiveContent:false},consent:{status:'not_required',scopes:[]},causality:{parentEventIds:[],supersedesEventIds:[],relatedEventIds:[]},
   payload:{fact:{uuid:'synthetic',type:'learning',project:123,content:'synthetic'}}}),path);
  await expect(rebuildProjectionsWithReport(db,path)).rejects.toThrow();
 }finally{db.close();store.cleanup();}
});

