import {strict as assert} from 'node:assert';
import {readFileSync,writeFileSync,statfsSync} from 'node:fs';
import {discoverInventory,validateInventory,sourceHash} from '../scripts/quality-inventory';
const root='.planning/memory-resilience/',read=(p:string)=>JSON.parse(readFileSync(p,'utf8')),save=(p:string,v:unknown)=>writeFileSync(p,JSON.stringify(v,null,2)+'\n');
const current=read('.git/q100-semantic-compat.json'),native=read('.git/q100-semantic-native.json'),measure=read('.git/q100-semantic-measure.json'),faults=read('.git/q100-semantic-faults.json');
for(const proof of [current,native,measure,faults])for(const row of proof.sourceInputs)assert.equal(sourceHash(readFileSync(row.path,'utf8')),row.sourceHash,row.path);
assert.deepEqual(current.sourceInputs,native.sourceInputs);
for(const run of [current,...native.runs]){assert.equal(run.exit,0);assert(run.output.includes('294 pass')&&run.output.includes('0 fail')&&run.output.includes('2426 expect()'));}
assert.equal(measure.runs[0].exit,0);assert.equal(faults.runs.length,9);assert.equal(faults.runs[0].exit,0);
for(const run of faults.runs.slice(1)){assert.equal(run.exit,1);assert(run.output.includes('(fail)'));}
assert.equal(readFileSync('.git/q100-semantic-test-types.txt','utf8').trim(),'');assert(readFileSync('.git/q100-semantic-isolation.txt','utf8').includes('PASS (no violations)'));
const red=readFileSync('.git/q100-semantic-coercion-red.txt','utf8');assert(red.includes('Received promise that resolved')&&red.includes('1 fail'));
const ledger=read(root+'work-items.json'),get=(id:string)=>ledger.items.find((i:any)=>i.id===id),parent=get('Q100.3.2');
